--
-- Estructura de tabla para la tabla `anotacion`
--

CREATE TABLE `anotacion` (
  `IdAnot` int(11) NOT NULL,
  `IdObs` int(11) NOT NULL,
  `NomProfCread` varchar(30) NOT NULL,
  `TipoFalta` varchar(10) NOT NULL,
  `DescFalta` text NOT NULL,
  `FecCreacion` timestamp NOT NULL DEFAULT current_timestamp(),
  `NomProfModif` varchar(30) NOT NULL DEFAULT 'Ninguno',
  `FecModif` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Disparadores `anotacion`
--
DELIMITER $$
CREATE TRIGGER `Despues_Crear_Anotacion` AFTER INSERT ON `anotacion` FOR EACH ROW BEGIN
  INSERT INTO historial_operaciones (IdAnotaOpera,IdEstOpera,NomProfOpera,TipoFalAntOpera, DescAntOpera, FecModifOpera,TipoCambOpera)
  VALUES (NEW.IdAnot, NEW.IdObs,NEW.NomProfCread,NEW.TipoFalta,NEW.DescFalta, NOW(),"Insercion");
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `Despues_Eliminar_Anotacion` AFTER DELETE ON `anotacion` FOR EACH ROW BEGIN
  INSERT INTO historial_operaciones (IdAnotaOpera,IdEstOpera,NomProfOpera,TipoFalAntOpera,DescAntOpera,FecModifOpera,TipoCambOpera)
  VALUES (OLD.IdAnot,OLD.IdObs,OLD.NomProfCread,OLD.TipoFalta,OLD.DescFalta, NOW(),"Eliminacion");
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `Despues_Modificar_Inventario` AFTER UPDATE ON `anotacion` FOR EACH ROW BEGIN
  INSERT INTO historial_operaciones (IdAnotaOpera,IdEstOpera,NomProfOpera,TipoFalAntOpera, DescAntOpera, FecModifOpera,TipoCambOpera)
  VALUES (OLD.IdAnot,  OLD.IdObs, OLD.NomProfCread,OLD.TipoFalta,OLD.DescFalta, NOW(),"Modificacion");
END
$$
DELIMITER ;

